// Notation: strings are mutable byte arrays. All three functions are pure byte
// transforms; no multibyte/UTF-8 awareness, no locale awareness, no trimming,
// no whitespace collapsing, no empty-string special case.
// In the evidence rows below, non-printable / non-ASCII bytes are written \xNN;
// everything else is literal. Outputs are quoted with '...' to make leading and
// trailing spaces unambiguous.

FUNCTION ascii_toupper(b: byte) -> byte:
    IF 0x61 <= b <= 0x7A THEN RETURN b - 0x20 ELSE RETURN b       // 'a'..'z' only

FUNCTION ascii_tolower(b: byte) -> byte:
    IF 0x41 <= b <= 0x5A THEN RETURN b + 0x20 ELSE RETURN b       // 'A'..'Z' only

// NOTE: these are the C/"POSIX"-locale toupper/tolower tables. Verified byte-by-byte
// for all 255 passable byte values: NO byte outside 0x41-0x5A / 0x61-0x7A is ever
// remapped (0x80-0xFF, incl. Latin-1 0xC9/0xE9 and UTF-8 lead/continuation bytes,
// pass through untouched). Output byte length always equals input byte length.


// ---------------------------------------------------------------- humanize -----
// = "underscores to spaces, then uppercase the FIRST BYTE"
FUNCTION humanize(s: bytes) -> bytes:
    out = copy_of(s)
    FOR i FROM 0 TO length(out) - 1:                  // unconditional global pass
        IF out[i] == 0x5F ('_') THEN out[i] = 0x20 (' ')
    IF length(out) > 0 THEN
        out[0] = ascii_toupper(out[0])                 // FIRST BYTE, not first letter
    RETURN out

// What humanize does NOT do (all refuted by probe):
//   - does NOT lowercase or otherwise touch bytes 1..n-1  ('cAT_id' -> 'CAT id')
//   - does NOT apply underscore()/decamelize        ('FooBar_id' -> 'FooBar id')
//   - does NOT strip a trailing "_id"               (W='' -> input '_id' -> ' id')
//   - does NOT touch '-', '.', or any other byte    ('a-b_id' -> 'A-b id')
//   - does NOT collapse or trim runs of spaces      ('a__b_id' -> 'A  b id')
//   - does NOT skip leading non-letters to find a letter: if out[0] is a space,
//     digit or punctuation it is passed to toupper (a no-op) and NO later byte is
//     uppercased  ('_x_id' -> ' x id',  '-foo_id' -> '-foo id',  '1a_id' -> '1a id')
// The two steps are order-independent as observed, because toupper('_')=='_' and
// toupper(' ')==' ' (see UNOBSERVABLE).


// ---------------------------------------------------------------- titleize -----
// = "downcase everything, then uppercase every byte that starts a
//    SPACE(0x20)-delimited run"
FUNCTION titleize(s: bytes) -> bytes:
    out = copy_of(s)
    FOR i FROM 0 TO length(out) - 1:                  // pass 1: global downcase
        out[i] = ascii_tolower(out[i])
    FOR i FROM 0 TO length(out) - 1:                  // pass 2: word starts
        IF i == 0 OR out[i-1] == 0x20 (' ') THEN
            out[i] = ascii_toupper(out[i])
    RETURN out

// Equivalent formulation (indistinguishable on every input tested):
//     tokens = split(s, on exactly one 0x20, keeping empty tokens)
//     for each token t: t = ascii_toupper(t[0]) + ascii_tolower(t[1..])
//     return join(tokens, 0x20)
//
// Word-boundary set is EXACTLY {0x20}. Established by brute force: for every byte
// b in 0x01..0xFF the input "Aa"+b+"Bb" was fed to titleize; ONLY b == 0x20
// produced 'Aa Bb' (uppercased 'B'). Non-boundaries explicitly include
// TAB 0x09, LF 0x0A, VT 0x0B, FF 0x0C, CR 0x0D, 0x01, 0x7F, NBSP-byte 0xA0,
// '_' 0x5F, '-' 0x2D, '.' 0x2E, '+' 0x2B, '/' 0x2F, all digits, all high bytes.
// Index 0 always counts as a word start.
// Consequences: a boundary byte that is not in 'a'..'z' is left as-is and does NOT
// "carry over" the capitalization to the next byte ('1abc' -> '1abc',
// '+a +b' -> '+a +b', '1a 2b' -> '1a 2b'). Leading/trailing/repeated spaces are
// preserved verbatim ('  lead' -> '  Lead', 'trail  ' -> 'Trail  ',
// 'foo  bar baz' -> 'Foo  Bar Baz'). No underscore()/humanize() is applied first
// ('foo_bar' -> 'Foo_bar', NOT 'Foo Bar'), and no camel-case splitting occurs
// ('FooBar' -> 'Foobar').


// --------------------------------------------------------------- dasherize -----
// = "every '_' becomes '-'; nothing else changes"
FUNCTION dasherize(s: bytes) -> bytes:
    out = copy_of(s)
    FOR i FROM 0 TO length(out) - 1:
        IF out[i] == 0x5F ('_') THEN out[i] = 0x2D ('-')
    RETURN out

// Case is fully preserved ('ABC_DEF' -> 'ABC-DEF', 'FooBar' -> 'FooBar').
// Every run of k underscores becomes k dashes, with no collapsing
// ('a__________b' -> 'a----------b'). Verified over all 255 byte values that no
// byte other than 0x5F is ever altered. dasherize('') == ''.
